 26→  CreateShareResponseDto,
 27→  ReceivedShareResponseDto,
 28→  SentShareResponseDto,
 29→  PendingRotationResponseDto,
 30→  ShareKeyResponseDto,
 31→} from './dto/share-response.dto';
 32→import { RequestWithUser } from '../common/types';
 33→
 34→@ApiTags('shares')
 35→@ApiBearerAuth()
 36→@UseGuards(JwtAuthGuard, ThrottlerGuard)
 37→@Controller('shares')
 38→export class SharesController {
 39→  constructor(private readonly sharesService: SharesService) {}
 40→
 41→  @Post()
 42→  @ApiOperation({
 43→    summary: 'Create a share',
 44→    description:
 45→      'Share an encrypted folder or file with another user. ' +
 46→      'The encryptedKey is the item key re-wrapped for the recipient via ECIES.',
 47→  })
 48→  @ApiResponse({ status: 201, description: 'Share created', type: CreateShareResponseDto })
 49→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 50→  @ApiResponse({ status: 404, description: 'Recipient not found' })
 51→  @ApiResponse({ status: 409, description: 'Share already exists or self-share' })
 52→  async createShare(
 53→    @Request() req: RequestWithUser,
 54→    @Body() dto: CreateShareDto
 55→  ): Promise<{
 56→    shareId: string;
 57→    itemType: string;
 58→    ipnsName: string;
 59→    itemName: string;
 60→    encryptedKey: string;
 61→    createdAt: Date;
 62→  }> {
 63→    const share = await this.sharesService.createShare(req.user.id, dto);
 64→    return {
 65→      shareId: share.id,
 66→      itemType: share.itemType,
 67→      ipnsName: share.ipnsName,
 68→      itemName: share.itemName,
 69→      encryptedKey: share.encryptedKey.toString('hex'),
 70→      createdAt: share.createdAt,
 71→    };
 72→  }
 73→
 74→  @Get('received')
 75→  @ApiOperation({
 76→    summary: 'List received shares',
 77→    description: 'Get all active, non-hidden shares received by the authenticated user.',
 78→  })
 79→  @ApiResponse({
 80→    status: 200,
 81→    description: 'List of received shares',
 82→    type: [ReceivedShareResponseDto],
 83→  })
 84→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 85→  async getReceivedShares(@Request() req: RequestWithUser): Promise<
 86→    Array<{
 87→      shareId: string;
 88→      sharerPublicKey: string;
 89→      itemType: string;
 90→      ipnsName: string;
 91→      itemName: string;
 92→      encryptedKey: string;
 93→      createdAt: Date;
 94→    }>
 95→  > {
 96→    const shares = await this.sharesService.getReceivedShares(req.user.id);
 97→    return shares.map((s) => ({
 98→      shareId: s.id,
 99→      sharerPublicKey: s.sharer.publicKey,
100→      itemType: s.itemType,
101→      ipnsName: s.ipnsName,
102→      itemName: s.itemName,
103→      encryptedKey: s.encryptedKey.toString('hex'),
104→      createdAt: s.createdAt,
105→    }));
106→  }
107→
108→  @Get('sent')
109→  @ApiOperation({
110→    summary: 'List sent shares',
111→    description: 'Get all active shares created by the authenticated user.',
112→  })
113→  @ApiResponse({ status: 200, description: 'List of sent shares', type: [SentShareResponseDto] })
114→  @ApiResponse({ status: 401, description: 'Unauthorized' })
115→  async getSentShares(@Request() req: RequestWithUser): Promise<
116→    Array<{
117→      shareId: string;
118→      recipientPublicKey: string;
119→      itemType: string;
120→      ipnsName: string;
121→      itemName: string;
122→      createdAt: Date;
123→    }>
124→  > {
125→    const shares = await this.sharesService.getSentShares(req.user.id);
126→    return shares.map((s) => ({
127→      shareId: s.id,
128→      recipientPublicKey: s.recipient.publicKey,
129→      itemType: s.itemType,
130→      ipnsName: s.ipnsName,
131→      itemName: s.itemName,
132→      createdAt: s.createdAt,
133→    }));
134→  }
135→
136→  @Get('lookup')
137→  @ApiOperation({
138→    summary: 'Look up user by public key',
139→    description: 'Verify a public key belongs to a registered CipherBox user.',
140→  })
141→  @ApiQuery({
142→    name: 'publicKey',
143→    description: 'Uncompressed secp256k1 public key (0x04...)',
144→    required: true,
145→  })
146→  @ApiResponse({ status: 200, description: 'User found' })
147→  @ApiResponse({ status: 401, description: 'Unauthorized' })
148→  @ApiResponse({ status: 404, description: 'User not found' })
149→  async lookupUser(@Query('publicKey') publicKey: string): Promise<{ exists: boolean }> {
150→    if (!publicKey || !/^0x04[0-9a-fA-F]{128}$/.test(publicKey)) {
151→      throw new BadRequestException(
152→        'Invalid public key format. Expected uncompressed secp256k1 key: 0x04 + 128 hex chars'
153→      );
154→    }
155→
156→    const exists = await this.sharesService.lookupUserByPublicKey(publicKey);
157→    if (!exists) {
158→      throw new NotFoundException('User not found');
159→    }
160→    return { exists: true };
161→  }
162→
163→  @Get('pending-rotations')
164→  @ApiOperation({
165→    summary: 'Get pending rotations',
166→    description:
167→      'Get shares that have been revoked but not yet key-rotated. ' +
168→      'Used by the client to detect lazy rotation needs before folder modification.',
169→  })
170→  @ApiResponse({
