  4→  Get,
  5→  Delete,
  6→  Body,
  7→  HttpCode,
  8→  HttpStatus,
  9→  UseGuards,
 10→  Request,
 11→  Res,
 12→  Req,
 13→  UnauthorizedException,
 14→  BadRequestException,
 15→} from '@nestjs/common';
 16→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
 17→import { Response, Request as ExpressRequest } from 'express';
 18→import { AuthService } from './auth.service';
 19→import { LoginDto, LoginResponseDto } from './dto/login.dto';
 20→import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
 21→import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
 22→import {
 23→  LinkMethodDto,
 24→  AuthMethodResponseDto,
 25→  UnlinkMethodDto,
 26→  UnlinkMethodResponseDto,
 27→} from './dto/link-method.dto';
 28→import { DeleteAccountDto, DeleteAccountResponseDto } from './dto/delete-account.dto';
 29→import { ThrottlerGuard } from '@nestjs/throttler';
 30→import { Throttle } from '@nestjs/throttler';
 31→import { JwtAuthGuard } from './guards/jwt-auth.guard';
 32→import { User } from './entities/user.entity';
 33→import { MetricsService } from '../metrics/metrics.service';
 34→
 35→interface RequestWithUser extends Request {
 36→  user: User;
 37→}
 38→
 39→// Cookie configuration
 40→const REFRESH_TOKEN_COOKIE_OPTIONS = {
 41→  httpOnly: true,
 42→  secure: process.env.NODE_ENV === 'production',
 43→  sameSite: 'lax' as const,
 44→  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
 45→  path: '/auth', // Only sent to auth endpoints
 46→};
 47→
 48→@ApiTags('Auth')
 49→@Controller('auth')
 50→export class AuthController {
 51→  constructor(
 52→    private authService: AuthService,
 53→    private readonly metricsService: MetricsService
 54→  ) {}
 55→
 56→  @Post('login')
 57→  @HttpCode(HttpStatus.OK)
 58→  @UseGuards(ThrottlerGuard)
 59→  @Throttle({ default: { limit: 10, ttl: 60000 } })
 60→  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
 61→  @ApiResponse({
 62→    status: 200,
 63→    description: 'Successfully authenticated',
 64→    type: LoginResponseDto,
 65→  })
 66→  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
 67→  async login(
 68→    @Body() loginDto: LoginDto,
 69→    @Req() req: ExpressRequest,
 70→    @Res({ passthrough: true }) res: Response
 71→  ): Promise<LoginResponseDto> {
 72→    const result = await this.authService.login(loginDto);
 73→    this.metricsService.authLogins.inc({
 74→      method: 'web3auth',
 75→      new_user: String(result.isNewUser),
 76→    });
 77→    const isDesktop = req.headers['x-client-type'] === 'desktop';
 78→
 79→    if (isDesktop) {
 80→      // Desktop clients: return refreshToken in response body (no cookie)
 81→      // For scoped temp auth (REQUIRED_SHARE), refreshToken is empty string → omitted
 82→      return {
 83→        accessToken: result.accessToken,
 84→        refreshToken: result.refreshToken || undefined,
 85→        isNewUser: result.isNewUser,
 86→      };
 87→    }
 88→
 89→    // Web clients: set refresh token in HTTP-only cookie (skip for scoped temp auth)
 90→    if (result.refreshToken) {
 91→      res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
 92→    }
 93→
 94→    return {
 95→      accessToken: result.accessToken,
 96→      isNewUser: result.isNewUser,
 97→    };
 98→  }
 99→
100→  @Post('refresh')
101→  @HttpCode(HttpStatus.OK)
102→  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
103→  @ApiResponse({
104→    status: 200,
105→    description: 'Tokens refreshed successfully',
106→    type: TokenResponseDto,
107→  })
108→  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
109→  async refresh(
110→    @Req() req: ExpressRequest,
111→    @Body() body: DesktopRefreshDto,
112→    @Res({ passthrough: true }) res: Response
113→  ): Promise<TokenResponseDto> {
114→    const isDesktop = req.headers['x-client-type'] === 'desktop';
115→
116→    let refreshToken: string | undefined;
117→
118→    if (isDesktop) {
119→      // Desktop clients: read refresh token from request body
120→      refreshToken = body?.refreshToken;
121→    } else {
122→      // Web clients: read refresh token from cookie
123→      refreshToken = req.cookies?.['refresh_token'];
124→    }
125→
126→    if (!refreshToken) {
127→      throw new UnauthorizedException('No refresh token');
128→    }
129→
130→    const result = await this.authService.refreshByToken(refreshToken);
131→
132→    if (isDesktop) {
133→      // Desktop clients: return new refreshToken in response body (no cookie)
134→      return {
135→        accessToken: result.accessToken,
136→        refreshToken: result.refreshToken,
137→        email: result.email,
138→      };
139→    }
140→
141→    // Web clients: set new refresh token in HTTP-only cookie (rotation)
142→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
143→
144→    return {
145→      accessToken: result.accessToken,
146→      email: result.email,
147→    };
148→  }
149→
150→  @Post('logout')
151→  @HttpCode(HttpStatus.OK)
152→  @UseGuards(JwtAuthGuard)
153→  @ApiBearerAuth()
154→  @ApiOperation({ summary: 'Logout user and invalidate all refresh tokens' })
155→  @ApiResponse({
156→    status: 200,
157→    description: 'Successfully logged out',
158→    type: LogoutResponseDto,
159→  })
160→  @ApiResponse({ status: 401, description: 'Unauthorized' })
161→  async logout(
162→    @Request() req: RequestWithUser,
163→    @Res({ passthrough: true }) res: Response
164→  ): Promise<LogoutResponseDto> {
165→    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
166→
167→    if (!isDesktop) {
168→      // Web clients: clear the refresh token cookie
169→      res.clearCookie('refresh_token', { path: '/auth' });
170→    }
171→
172→    return this.authService.logout(req.user.id);
173→  }
174→
175→  @Delete('account')
176→  @HttpCode(HttpStatus.OK)
177→  @UseGuards(ThrottlerGuard)
178→  @Throttle({ default: { limit: 3, ttl: 60000 } })
179→  @UseGuards(JwtAuthGuard)
180→  @ApiBearerAuth()
181→  @ApiOperation({ summary: 'Permanently delete user account and all associated data' })
182→  @ApiResponse({
183→    status: 200,
184→    description: 'Account deleted successfully',
185→    type: DeleteAccountResponseDto,
186→  })
187→  @ApiResponse({ status: 400, description: 'Invalid confirmation or account not found' })
188→  @ApiResponse({ status: 401, description: 'Unauthorized' })
189→  async deleteAccount(
190→    @Request() req: RequestWithUser,
191→    @Body() dto: DeleteAccountDto,
192→    @Res({ passthrough: true }) res: Response
193→  ): Promise<DeleteAccountResponseDto> {
194→    if (dto.confirmation !== 'DELETE') {
195→      throw new BadRequestException('Confirmation must be the string "DELETE"');
196→    }
197→    const result = await this.authService.deleteAccount(req.user.id);
198→    const isDesktop = (req as unknown as ExpressRequest).headers['x-client-type'] === 'desktop';
199→    if (!isDesktop) {
200→      res.clearCookie('refresh_token', { path: '/auth' });
201→    }
202→    return result;
203→  }
204→
205→  @Get('methods')
206→  @UseGuards(JwtAuthGuard)
207→  @ApiBearerAuth()
208→  @ApiOperation({ summary: 'Get all linked auth methods for the current user' })
209→  @ApiResponse({
210→    status: 200,
211→    description: 'List of linked auth methods',
212→    type: [AuthMethodResponseDto],
213→  })
214→  @ApiResponse({ status: 401, description: 'Unauthorized' })
215→  async getMethods(@Request() req: RequestWithUser): Promise<AuthMethodResponseDto[]> {
216→    return this.authService.getLinkedMethods(req.user.id);
217→  }
218→
219→  @Post('link')
220→  @HttpCode(HttpStatus.OK)
221→  @UseGuards(JwtAuthGuard)
222→  @ApiBearerAuth()
223→  @ApiOperation({ summary: 'Link a new auth method to the current user account' })
224→  @ApiResponse({
225→    status: 200,
226→    description: 'Auth method linked successfully, returns updated list of methods',
227→    type: [AuthMethodResponseDto],
228→  })
229→  @ApiResponse({ status: 400, description: 'Auth method already linked or publicKey mismatch' })
230→  @ApiResponse({ status: 401, description: 'Unauthorized' })
231→  async linkMethod(
232→    @Request() req: RequestWithUser,
233→    @Body() linkDto: LinkMethodDto
234→  ): Promise<AuthMethodResponseDto[]> {
235→    return this.authService.linkMethod(req.user.id, linkDto);
236→  }
237→
238→  @Post('unlink')
239→  @HttpCode(HttpStatus.OK)
240→  @UseGuards(JwtAuthGuard)
241→  @ApiBearerAuth()
242→  @ApiOperation({ summary: 'Unlink an auth method from the current user account' })
243→  @ApiResponse({
244→    status: 200,
245→    description: 'Auth method unlinked successfully',
246→    type: UnlinkMethodResponseDto,
247→  })
248→  @ApiResponse({ status: 400, description: 'Cannot unlink last auth method or method not found' })
249→  @ApiResponse({ status: 401, description: 'Unauthorized' })
250→  async unlinkMethod(
251→    @Request() req: RequestWithUser,
252→    @Body() unlinkDto: UnlinkMethodDto
253→  ): Promise<UnlinkMethodResponseDto> {
254→    await this.authService.unlinkMethod(req.user.id, unlinkDto.methodId);
255→    return { success: true };
256→  }
257→
258→  @Post('test-login')
259→  @HttpCode(HttpStatus.OK)
260→  @UseGuards(ThrottlerGuard)
261→  @Throttle({ default: { limit: 5, ttl: 900000 } })
262→  @ApiOperation({
263→    summary: 'Test-only login bypassing Core Kit (requires TEST_LOGIN_SECRET)',
264→  })
265→  @ApiResponse({
266→    status: 200,
267→    description: 'Test login successful',
268→    type: TestLoginResponseDto,
269→  })
270→  @ApiResponse({ status: 403, description: 'Test login not enabled' })
271→  @ApiResponse({ status: 401, description: 'Invalid secret' })
272→  async testLogin(
273→    @Body() dto: TestLoginDto,
274→    @Res({ passthrough: true }) res: Response
275→  ): Promise<TestLoginResponseDto> {
276→    const result = await this.authService.testLogin(dto.email, dto.secret);
277→    this.metricsService.authLogins.inc({
278→      method: 'test',
279→      new_user: String(result.isNewUser),
280→    });
281→
282→    // Set refresh token cookie (same as normal login for web clients)
283→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
284→
285→    return {
