          sharerId,
          recipientId,
          itemType: 'folder',
          ipnsName: testIpnsName,
        })
      );
      expect(mockShareKeyRepo.create).toHaveBeenCalledTimes(1);
      expect(mockShareKeyRepo.save).toHaveBeenCalled();
